entries.syntax:
CREATE TABLE table_name (
  column1 data_type [column_attributes],
  column2 data_type [column_attributes]
);

INSERT INTO table_name (column1, column2)
VALUES (value1, value2);

INSERT INTO table_name
VALUES (value1, value2, ...);

UPDATE table_name
SET column1 = value1, column2 = value2
WHERE condition;

SELECT * FROM table_name;
SELECT column1, column2 FROM table_name;
SELECT expression FROM table_name;

SELECT grouping_column, AVG(value_column)
FROM table_name
GROUP BY grouping_column;

SELECT select_list
FROM left_table
INNER JOIN right_table ON left_table.key = right_table.key;

SELECT select_list
FROM left_table
LEFT [OUTER] JOIN right_table ON left_table.key = right_table.key;

SELECT select_list
FROM left_table
RIGHT [OUTER] JOIN right_table ON left_table.key = right_table.key;

SELECT select_list
FROM left_table
FULL [OUTER] JOIN right_table ON join_condition;

SELECT select_list
FROM left_table
INNER JOIN right_table USING (shared_column);

GRANT SELECT, UPDATE
ON database_name.table_name
TO 'user_name'@'host_name';

REVOKE SELECT, UPDATE
ON database_name.table_name
FROM 'user_name'@'host_name';
